mapper.select:

SELECT CTIME AS ctime, DATE_MONTH AS dateMonth, DATE_DAY AS dateDay, DATE_TIME AS dateTime, IN_MAIL AS inMail, OUT_MAIL AS outMail, FILE_SIZE AS fileSize, FTP AS ftp, TOTAL_SIZE AS totalSize
  FROM UI_USAGE_COMPARE
 WHERE CTIME >= #{startDate} 
   AND CTIME <= #{endDate}
 ORDER BY CTIME


SELECT MAX(CTIME) AS ctime, DATE_MONTH AS dateMonth, DATE_DAY AS dateDay, SUM(IN_MAIL) AS inMail, SUM(OUT_MAIL) AS outMail, SUM(FILE_SIZE) AS fileSize, SUM(FTP) AS ftp, SUM(TOTAL_SIZE) AS totalSize
  FROM UI_USAGE_COMPARE
 WHERE CTIME >= #{startDate}
   AND CTIME <= #{endDate} 
 GROUP BY DATE_MONTH, DATE_DAY
 ORDER BY DATE_MONTH, DATE_DAY


SELECT MAX(CTIME) AS ctime, DATE_MONTH AS dateMonth, SUM(IN_MAIL) AS inMail, SUM(OUT_MAIL) AS outMail, SUM(FILE_SIZE) AS fileSize, SUM(FTP) AS ftp, SUM(TOTAL_SIZE) AS totalSize
  FROM UI_USAGE_COMPARE
 WHERE CTIME >= #{startDate}
   AND CTIME <= #{endDate}
 GROUP BY DATE_MONTH
 ORDER BY DATE_MONTH


SELECT MAX(CTIME) AS ctime, DATE_MONTH AS dateMonth, DATE_WEEK_OF_MONTH AS dateWeekOfMonth, MAX(CTIME) AS ctime, SUM(IN_MAIL) AS inMail, SUM(OUT_MAIL) AS outMail, SUM(FILE_SIZE) AS fileSize, SUM(FTP) AS ftp, SUM(TOTAL_SIZE) AS totalSize
  FROM UI_USAGE_COMPARE
 WHERE CTIME >= #{startDate}
   AND CTIME <= #{endDate}
 GROUP BY DATE_MONTH, DATE_WEEK_OF_MONTH
 ORDER BY DATE_MONTH, DATE_WEEK_OF_MONTH
